// Requisito defines model for Requisito.
type Requisito struct {
	// Atencao Motivos pelos quais o requisito não está bem cuidado (vazio se está)
	Atencao      []Atencao `json:"atencao"`
	AtualizadoEm time.Time `json:"atualizado_em"`

	// Componentes Componentes a que o requisito se refere
	Componentes []string  `json:"componentes"`
	CriadoEm    time.Time `json:"criado_em"`

	// DerivaDe Requisitos dos quais este deriva (acima na cadeia)
	DerivaDe []string `json:"deriva_de"`

	// Derivados Requisitos que derivam deste (abaixo na cadeia)
	Derivados []string `json:"derivados"`
	Descricao string   `json:"descricao"`

	// Estado Calculado, nunca escrito à mão. Do menos ao mais maduro: nao_atendido (tarefa aberta fora de
	// andamento, ou nem tarefa nem execução), em_trabalho (tarefa em andamento), nao_validado
	// (tarefas todas concluídas, sem execução),
	// validacao_expirada (a última execução passou do prazo), validado. O estado próprio vem das
	// tarefas ligadas e da última execução; o estado é o menos maduro entre o próprio e o de cada
	// requisito abaixo. Sem tarefa e sem execução, um requisito com derivados é decidido só por eles.
	Estado EstadoDoRequisito `json:"estado"`

	// EstadoProprio Calculado, nunca escrito à mão. Do menos ao mais maduro: nao_atendido (tarefa aberta fora de
	// andamento, ou nem tarefa nem execução), em_trabalho (tarefa em andamento), nao_validado
	// (tarefas todas concluídas, sem execução),
	// validacao_expirada (a última execução passou do prazo), validado. O estado próprio vem das
	// tarefas ligadas e da última execução; o estado é o menos maduro entre o próprio e o de cada
	// requisito abaixo. Sem tarefa e sem execução, um requisito com derivados é decidido só por eles.
	EstadoProprio EstadoDoRequisito `json:"estado_proprio"`
	Id            string            `json:"id"`

	// Importancia Os pontos e a fatia entre irmãos sob cada pai, na ordem de deriva_de
	Importancia []Importancia `json:"importancia"`

	// LimitadoPor Requisitos logo abaixo que limitam o estado dele a um menos maduro que o próprio
	LimitadoPor []string `json:"limitado_por"`

	// Obsoleto Presente só no requisito obsoleto: quando e por quê. Ele continua consultável, mas não limita os pais nem pesa entre os irmãos.
	Obsoleto    *Obsoleto `json:"obsoleto,omitempty"`
	Organizacao string    `json:"organizacao"`
	Origem      *string   `json:"origem,omitempty"`

	// Peso Peso no total, de 0 a 1: o zero vale 1; cada requisito soma, sobre os pais, o peso do pai vezes a fatia sob ele
	Peso float32 `json:"peso"`

	// Prioridade Obsoleta, substituída pelos pontos de importância; guardada só como histórico.
	Prioridade *Prioridade `json:"prioridade,omitempty"`

	// Tarefas Tarefas que tentam atender este requisito
	Tarefas []string `json:"tarefas"`

	// TarefasAbertas Tarefas ligadas a este requisito que não estão concluídas
	TarefasAbertas []string `json:"tarefas_abertas"`
	Titulo         string   `json:"titulo"`

	// Trilhas Só ao obter um requisito: cada caminho do zero até ele, em títulos ("R-0001 … › R-0003 …")
	Trilhas        *[]string `json:"trilhas,omitempty"`
	UltimaExecucao *Execucao `json:"ultima_execucao,omitempty"`
}

